:root {
  --ink: #050409;
  --ink-2: #0b0812;
  --paper: #f8eee4;
  --muted: rgba(248, 238, 228, 0.56);
  --faint: rgba(248, 238, 228, 0.14);
  --hot: #ff4f78;
  --hot-2: #ff886f;
  --gold: #f4c68f;
  --aqua: #7fe8df;
  --violet: #9b6bff;
  --glass: rgba(11, 8, 17, 0.58);
  --border: rgba(255, 235, 219, 0.17);
  --display: "Bodoni 72", Didot, "Bodoni MT", "Times New Roman", serif;
  --sans: "Neue Haas Grotesk", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --mono: "SFMono-Regular", "Cascadia Mono", Consolas, monospace;
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--paper);
  touch-action: none;
  overscroll-behavior: none;
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  font-family: var(--sans);
}

body {
  position: fixed;
  inset: 0;
  min-height: 100dvh;
}

button { font: inherit; color: inherit; }
button:focus-visible { outline: 2px solid var(--aqua); outline-offset: 4px; }
.hidden { display: none !important; }

#scene {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  background: #05040a;
}

.fx {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 2;
}
.fx-vignette {
  background:
    radial-gradient(ellipse at 50% 50%, transparent 38%, rgba(4, 2, 8, 0.28) 70%, rgba(3, 2, 6, 0.74) 112%),
    linear-gradient(180deg, rgba(4, 2, 8, 0.2), transparent 24%, transparent 72%, rgba(4, 2, 8, 0.36));
}
.fx-grain {
  opacity: 0.045;
  mix-blend-mode: soft-light;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.86' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.7'/%3E%3C/svg%3E");
  background-size: 180px;
  animation: grain 0.4s steps(2) infinite;
}
.fx-scanline {
  opacity: 0.13;
  background: repeating-linear-gradient(180deg, transparent 0, transparent 3px, rgba(255,255,255,.03) 4px);
  mix-blend-mode: overlay;
}
@keyframes grain {
  0% { transform: translate(0, 0); }
  25% { transform: translate(-1%, 1%); }
  50% { transform: translate(1%, -1%); }
  75% { transform: translate(-1%, -1%); }
  100% { transform: translate(1%, 1%); }
}

/* ---------- shared chrome ---------- */

.screen {
  position: fixed;
  inset: 0;
  z-index: 10;
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--gold);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.27em;
  white-space: nowrap;
}
.eyebrow span {
  width: 36px;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--gold));
}
.eyebrow span:last-child { background: linear-gradient(90deg, var(--gold), transparent); }

.btn-primary {
  position: relative;
  border: 0;
  border-radius: 999px;
  min-width: 174px;
  height: 58px;
  padding: 0 34px;
  background: linear-gradient(100deg, #ff4f78 0%, #ff756f 58%, #ffc08e 100%);
  color: #18060a;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  cursor: pointer;
  box-shadow: 0 10px 34px rgba(255, 68, 111, 0.32), inset 0 1px 0 rgba(255,255,255,0.52);
  transition: transform 180ms ease, box-shadow 180ms ease, filter 180ms ease;
}
.btn-primary::after {
  content: "";
  position: absolute;
  inset: 5px;
  border: 1px solid rgba(24, 6, 10, 0.22);
  border-radius: inherit;
  pointer-events: none;
}
.btn-primary:hover { transform: translateY(-2px); filter: brightness(1.06); box-shadow: 0 16px 42px rgba(255, 68, 111, 0.4), inset 0 1px 0 rgba(255,255,255,0.6); }
.btn-primary:active { transform: translateY(0) scale(0.985); }

.text-btn {
  border: 0;
  background: none;
  padding: 12px 8px;
  color: var(--muted);
  cursor: pointer;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  transition: color 160ms ease;
}
.text-btn:hover { color: var(--paper); }

/* ---------- title ---------- */

.title-screen {
  display: flex;
  align-items: center;
  background:
    linear-gradient(90deg, rgba(4, 2, 8, 0.95) 0%, rgba(4, 2, 8, 0.78) 30%, rgba(4, 2, 8, 0.22) 62%, rgba(4, 2, 8, 0.07) 100%),
    radial-gradient(ellipse at 81% 42%, transparent 3%, rgba(4, 2, 8, 0.16) 60%, rgba(4, 2, 8, 0.56) 100%);
  transition: opacity 700ms ease, transform 900ms cubic-bezier(.2,.8,.2,1);
}
.title-screen.is-leaving { opacity: 0; transform: scale(1.035); pointer-events: none; }
.title-veil {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(4,2,8,.3), transparent 24%, transparent 72%, rgba(4,2,8,.8));
  pointer-events: none;
}
.title-content {
  position: relative;
  width: min(760px, 58vw);
  margin-left: clamp(24px, 7vw, 112px);
  margin-top: -3vh;
  z-index: 2;
  animation: title-in 1200ms cubic-bezier(.2,.8,.2,1) both;
}
@keyframes title-in {
  from { opacity: 0; transform: translateY(22px); }
  to { opacity: 1; transform: translateY(0); }
}
.title-content .eyebrow { margin-bottom: 30px; }
.wordmark {
  margin: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  line-height: 0.72;
  letter-spacing: -0.055em;
  text-shadow: 0 16px 66px rgba(0,0,0,.6);
}
.wordmark-thin {
  font-family: var(--display);
  font-style: italic;
  font-weight: 400;
  font-size: clamp(64px, 9.6vw, 142px);
  color: #f7e8dd;
  margin-left: 0.07em;
  transform: translateY(0.06em);
}
.wordmark-hot {
  font-family: var(--sans);
  font-size: clamp(82px, 13.3vw, 196px);
  font-weight: 900;
  letter-spacing: -0.07em;
  background: linear-gradient(102deg, #fff3e9 0%, #ffd7c5 12%, #ff6384 49%, #ff876f 78%, #ffbf8c 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 8px 34px rgba(255, 68, 111, 0.24));
}
.tagline {
  margin: 30px 0 0;
  font-family: var(--display);
  font-size: clamp(19px, 2vw, 28px);
  line-height: 1.2;
  font-weight: 400;
  color: rgba(250, 239, 229, 0.84);
  letter-spacing: 0.01em;
}
.tagline em { color: var(--gold); }
.title-lede {
  width: min(430px, 100%);
  margin: 17px 0 0;
  color: rgba(247, 238, 230, 0.5);
  font-size: 13px;
  line-height: 1.7;
  letter-spacing: 0.015em;
}
.title-actions {
  display: flex;
  align-items: center;
  gap: 22px;
  margin-top: 34px;
}
.rating {
  display: flex;
  align-items: center;
  gap: 10px;
  color: rgba(248, 238, 228, 0.47);
}
.rating strong {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(244, 198, 143, 0.42);
  border-radius: 50%;
  font-size: 11px;
  color: var(--gold);
}
.rating span {
  font-size: 8px;
  line-height: 1.4;
  letter-spacing: 0.17em;
  text-transform: uppercase;
}
.title-fineprint {
  margin: 16px 0 0;
  color: rgba(248, 238, 228, 0.27);
  font-size: 9px;
  letter-spacing: 0.08em;
}
.title-footer {
  position: absolute;
  z-index: 3;
  left: clamp(24px, 7vw, 112px);
  right: clamp(24px, 7vw, 112px);
  bottom: calc(30px + var(--safe-b));
  display: flex;
  align-items: center;
  gap: 22px;
  color: rgba(248, 238, 228, 0.6);
  font-size: 9px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.control-tip { display: flex; align-items: center; gap: 8px; }
.keycap {
  border: 1px solid rgba(248, 238, 228, 0.19);
  border-radius: 4px;
  padding: 4px 7px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.08em;
  color: rgba(248, 238, 228, 0.73);
  background: rgba(255,255,255,.03);
}
.title-edition {
  margin-left: auto;
  color: rgba(244, 198, 143, 0.56);
  letter-spacing: 0.2em;
}
.title-orbit {
  position: absolute;
  right: 11vw;
  top: 50%;
  width: 260px;
  height: 260px;
  transform: translateY(-50%);
  pointer-events: none;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 50%;
}
.title-orbit::before, .title-orbit::after {
  content: "";
  position: absolute;
  border-radius: 50%;
  border: 1px solid rgba(255, 111, 135, 0.16);
}
.title-orbit::before { inset: 24px; }
.title-orbit::after { inset: 68px; border-color: rgba(255,255,255,.06); }
.title-orbit span {
  position: absolute;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--hot);
  box-shadow: 0 0 16px 3px rgba(255, 79, 120, .6);
}
.title-orbit span:nth-child(1) { top: 38px; left: 60px; }
.title-orbit span:nth-child(2) { top: 142px; right: 17px; background: var(--gold); box-shadow: 0 0 16px 3px rgba(244,198,143,.4); }
.title-orbit span:nth-child(3) { bottom: 22px; left: 98px; width: 3px; height: 3px; background: var(--aqua); box-shadow: 0 0 12px 2px rgba(127,232,223,.5); }

/* ---------- HUD ---------- */

.hud {
  position: fixed;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  animation: hud-in 650ms ease both;
}
@keyframes hud-in { from { opacity: 0; } to { opacity: 1; } }
.hud button, .hud a, .joystick { pointer-events: auto; }
.hud-top {
  position: absolute;
  top: calc(20px + var(--safe-t));
  left: calc(24px + var(--safe-l));
  right: calc(24px + var(--safe-r));
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: start;
  gap: 20px;
}
.hud-brand { display: flex; align-items: center; gap: 11px; }
.hud-brand-mark {
  width: 26px;
  height: 31px;
  position: relative;
  display: block;
  border: 1px solid rgba(255, 118, 133, .65);
  border-radius: 0 0 14px 14px;
  transform: rotate(45deg) scale(.66);
  box-shadow: inset 0 0 16px rgba(255, 79, 120, .16), 0 0 18px rgba(255, 79, 120, .12);
}
.hud-brand-mark::after {
  content: "";
  position: absolute;
  inset: 7px;
  border: 1px solid rgba(244, 198, 143, .52);
  border-radius: inherit;
}
.hud-brand div { display: flex; flex-direction: column; line-height: .92; }
.hud-brand strong { font-size: 11px; letter-spacing: .2em; font-weight: 700; }
.hud-brand span { font-family: var(--display); font-style: italic; font-size: 16px; color: var(--gold); letter-spacing: .01em; }
.objective-card {
  display: flex;
  flex-direction: column;
  gap: 5px;
  align-items: center;
  padding: 8px 18px 9px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 999px;
  background: rgba(8, 6, 14, 0.32);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}
.objective-label {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--gold);
  font-size: 7px;
  letter-spacing: .22em;
  font-weight: 700;
}
.objective-label i { width: 4px; height: 4px; background: var(--hot); border-radius: 50%; box-shadow: 0 0 8px var(--hot); }
#objectiveText { font-family: var(--display); font-size: 14px; font-style: italic; color: rgba(255,244,235,.86); letter-spacing: .02em; }
.hud-right { display: flex; justify-content: flex-end; align-items: center; gap: 13px; }
.clock {
  display: flex;
  align-items: baseline;
  gap: 4px;
  padding: 7px 13px;
  border: 1px solid rgba(255,255,255,.09);
  border-radius: 999px;
  background: rgba(8, 6, 14, 0.3);
  backdrop-filter: blur(12px);
}
.clock span { font-family: var(--mono); font-size: 12px; letter-spacing: .08em; color: rgba(255,246,238,.9); }
.clock small { font-size: 7px; color: var(--gold); letter-spacing: .12em; }
.round-btn {
  width: 37px;
  height: 37px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255,255,255,.1);
  border-radius: 50%;
  background: rgba(8, 6, 14, 0.32);
  color: rgba(255,246,238,.63);
  cursor: pointer;
  backdrop-filter: blur(12px);
}
.round-btn svg { width: 17px; height: 17px; fill: currentColor; }
.round-btn .icon-off { display: none; }
.round-btn.muted .icon-on { display: none; }
.round-btn.muted .icon-off { display: block; }
.round-btn:hover { color: var(--paper); border-color: rgba(255,255,255,.23); }

.hud-bottom {
  position: absolute;
  left: calc(25px + var(--safe-l));
  right: calc(25px + var(--safe-r));
  bottom: calc(25px + var(--safe-b));
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
}
.joystick {
  width: 124px;
  height: 124px;
  border: 1px solid rgba(255,255,255,.11);
  border-radius: 50%;
  position: relative;
  flex: 0 0 auto;
  background: radial-gradient(circle, rgba(255,255,255,.035) 0 42%, rgba(8,6,14,.18) 43% 100%);
  backdrop-filter: blur(8px);
  touch-action: none;
}
.joystick-ring {
  position: absolute;
  inset: 18px;
  border: 1px dashed rgba(255,255,255,.1);
  border-radius: 50%;
}
.joystick-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 50px;
  height: 50px;
  margin: -25px 0 0 -25px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid rgba(255, 226, 211, .18);
  background: linear-gradient(145deg, rgba(255,255,255,.15), rgba(255,255,255,.035));
  box-shadow: 0 8px 26px rgba(0,0,0,.4);
  color: rgba(255, 240, 230, .55);
  transition: transform 70ms linear;
}
.joystick-knob svg { width: 22px; height: 22px; fill: currentColor; opacity: .65; }
.joystick-label {
  position: absolute;
  left: 50%;
  bottom: -20px;
  transform: translateX(-50%);
  font-size: 7px;
  letter-spacing: .25em;
  color: rgba(248,238,228,.28);
}
.joystick.active { border-color: rgba(255, 121, 137, .3); box-shadow: 0 0 40px rgba(255,79,120,.1); }

.center-hint {
  align-self: flex-end;
  margin-bottom: 3px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border-radius: 99px;
  background: rgba(8,6,14,.24);
  border: 1px solid rgba(255,255,255,.055);
  color: rgba(248,238,228,.37);
  font-size: 8px;
  letter-spacing: .1em;
  text-transform: uppercase;
  transition: opacity 500ms ease;
}
.pulse-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--hot); box-shadow: 0 0 10px var(--hot); animation: blink 2s infinite; }
@keyframes blink { 0%,100% { opacity: .35; } 50% { opacity: 1; } }

.action-cluster {
  position: relative;
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}
.context-prompt {
  text-align: center;
  padding: 8px 16px;
  border-radius: 10px;
  border: 1px solid rgba(255, 121, 137, 0.22);
  background: rgba(10, 6, 15, .58);
  backdrop-filter: blur(14px);
  box-shadow: 0 10px 30px rgba(0,0,0,.24);
  animation: context-in 240ms ease both;
}
@keyframes context-in { from { opacity: 0; transform: translateY(5px); } to { opacity: 1; transform: translateY(0); } }
.context-prompt span { display: block; font-size: 9px; font-weight: 800; letter-spacing: .23em; color: var(--paper); }
.context-prompt small { display: block; margin-top: 2px; font-family: var(--display); font-style: italic; font-size: 12px; color: var(--gold); letter-spacing: .02em; }
.action-btn {
  width: 100px;
  height: 100px;
  border-radius: 50%;
  border: 1px solid rgba(255, 148, 156, 0.38);
  background:
    radial-gradient(circle at 35% 28%, rgba(255,255,255,.25), transparent 36%),
    radial-gradient(circle at 50% 58%, #ff6f83 0%, #ff4e73 36%, #cb244e 100%);
  color: #fff5f0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  cursor: pointer;
  position: relative;
  box-shadow: 0 8px 34px rgba(255, 57, 99, .32), inset 0 1px 1px rgba(255,255,255,.4);
  transition: transform 150ms ease, filter 180ms ease, box-shadow 180ms ease;
}
.action-btn::before {
  content: "";
  position: absolute;
  inset: 8px;
  border: 1px solid rgba(255,255,255,.18);
  border-radius: 50%;
}
.action-btn svg { width: 31px; height: 31px; filter: drop-shadow(0 2px 4px rgba(88,0,20,.2)); }
.action-btn span:last-child { font-size: 8px; font-weight: 800; letter-spacing: .2em; }
.action-btn:hover { transform: scale(1.035); filter: brightness(1.07); box-shadow: 0 12px 44px rgba(255, 57, 99, .42); }
.action-btn:active { transform: scale(.97); }
.action-btn.inactive { opacity: .42; filter: saturate(.45); box-shadow: 0 5px 24px rgba(255,57,99,.13); }
.action-btn.ready { animation: actionPulse 2.1s ease-in-out infinite; }
@keyframes actionPulse {
  0%, 100% { box-shadow: 0 8px 34px rgba(255,57,99,.3), 0 0 0 0 rgba(255, 79, 120, 0); }
  50% { box-shadow: 0 8px 44px rgba(255,57,99,.44), 0 0 0 12px rgba(255, 79, 120, 0); }
}
.action-rings {
  position: absolute;
  inset: -12px;
  border-radius: 50%;
  border: 1px solid rgba(255,115,132,.12);
  pointer-events: none;
}
.action-rings::after { content: ""; position: absolute; inset: -10px; border-radius: 50%; border: 1px solid rgba(255,115,132,.07); }

.toast {
  position: absolute;
  left: 50%;
  top: calc(100px + var(--safe-t));
  transform: translate(-50%, -7px);
  padding: 9px 18px;
  border: 1px solid rgba(244,198,143,.22);
  border-radius: 999px;
  background: rgba(9,6,14,.72);
  backdrop-filter: blur(16px);
  color: rgba(255,244,235,.84);
  font-size: 9px;
  letter-spacing: .14em;
  text-transform: uppercase;
  opacity: 0;
  pointer-events: none;
  transition: opacity 300ms ease, transform 300ms ease;
  white-space: nowrap;
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }
.toast.hot { border-color: rgba(255,79,120,.34); color: #ffd7df; }

.waypoint {
  position: absolute;
  top: calc(85px + var(--safe-t));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 8px;
  color: rgba(255,244,235,.67);
  font-size: 8px;
  letter-spacing: .18em;
  text-transform: uppercase;
  transition: opacity .2s;
}
.waypoint-arrow { display: inline-block; color: var(--hot); font-size: 13px; transform-origin: center; }
.waypoint small { color: rgba(248,238,228,.32); font-size: 7px; letter-spacing: .1em; }

.npc-tags { position: absolute; inset: 0; overflow: hidden; }
.npc-tag {
  position: absolute;
  left: 0;
  top: 0;
  transform: translate(-50%, -100%);
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 5px 9px 5px 7px;
  border-radius: 99px;
  border: 1px solid rgba(255,255,255,.15);
  background: rgba(8,5,13,.53);
  backdrop-filter: blur(10px);
  box-shadow: 0 4px 18px rgba(0,0,0,.22);
  transition: opacity 170ms ease;
  white-space: nowrap;
}
.npc-tag::after {
  content: "";
  position: absolute;
  left: 50%;
  bottom: -5px;
  width: 1px;
  height: 5px;
  background: rgba(255,255,255,.25);
}
.npc-tag .npc-heart { width: 14px; height: 14px; display: grid; place-items: center; border-radius: 50%; background: var(--npc-color, var(--hot)); color: #15070c; font-size: 8px; }
.npc-tag strong { font-size: 8px; letter-spacing: .16em; font-weight: 700; }
.npc-tag small { font-family: var(--mono); font-size: 7px; color: rgba(248,238,228,.43); letter-spacing: .02em; }
.npc-tag .npc-hot { color: var(--gold); }
.npc-tag.is-near { border-color: rgba(255, 113, 133, .55); background: rgba(27,8,16,.68); }

/* ---------- dialogue ---------- */

.overlay {
  position: fixed;
  inset: 0;
  z-index: 20;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 380ms ease, visibility 380ms;
}
.overlay:not(.hidden) { opacity: 1; visibility: visible; pointer-events: auto; }
.dialogue-overlay {
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
}
.dialogue-shade {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(180deg, rgba(4,2,8,.62) 0%, transparent 22%, transparent 38%, rgba(4,2,8,.75) 63%, rgba(4,2,8,.97) 100%),
    radial-gradient(ellipse at 50% 100%, rgba(255,79,120,.11), transparent 54%);
  pointer-events: none;
}
.dialogue-head {
  position: relative;
  z-index: 2;
  width: min(800px, calc(100% - 48px));
  margin: calc(24px + var(--safe-t)) auto 0;
  padding: 0 6px;
}
.spark-id {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 7px;
  letter-spacing: .23em;
  color: rgba(244,198,143,.75);
  font-weight: 700;
}
.spark-id i { width: 20px; height: 1px; background: rgba(244,198,143,.34); display: block; }
.spark-id b { font-weight: 700; color: var(--hot); }
.dialogue-title-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-top: 12px;
}
.dialogue-title-row h2 {
  margin: 0;
  font-family: var(--display);
  font-style: italic;
  font-weight: 400;
  font-size: clamp(36px, 5vw, 64px);
  line-height: 1;
  letter-spacing: -.025em;
  color: #fff1e6;
  text-shadow: 0 8px 34px rgba(0,0,0,.4);
}
.dialogue-title-row p {
  margin: 7px 0 0;
  font-size: 9px;
  letter-spacing: .15em;
  text-transform: uppercase;
  color: rgba(248,238,228,.36);
}
.heat-readout { display: flex; align-items: baseline; gap: 2px; padding-bottom: 5px; }
.heat-readout span { font-size: 7px; letter-spacing: .22em; color: rgba(244,198,143,.6); margin-right: 7px; }
.heat-readout strong { font-family: var(--display); font-size: 39px; line-height: 1; font-style: italic; color: var(--hot); }
.heat-readout small { font-family: var(--mono); font-size: 10px; color: var(--hot); }
.heat-track { width: 100%; height: 2px; background: rgba(255,255,255,.1); margin-top: 14px; overflow: hidden; }
.heat-track i { display: block; width: 0%; height: 100%; background: linear-gradient(90deg, var(--gold), var(--hot), #ffa07e); box-shadow: 0 0 10px var(--hot); transition: width 600ms cubic-bezier(.2,.8,.2,1); }

.dialogue-panel {
  position: absolute;
  z-index: 3;
  left: 50%;
  bottom: 0;
  transform: translateX(-50%);
  width: min(800px, 100%);
  padding: 20px clamp(24px, 4vw, 48px) calc(30px + var(--safe-b));
  background: linear-gradient(180deg, transparent 0%, rgba(6,4,10,.72) 12%, rgba(6,4,10,.94) 100%);
}
.close-btn {
  position: absolute;
  top: 7px;
  right: calc(18px + var(--safe-r));
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,.12);
  background: rgba(255,255,255,.02);
  color: rgba(248,238,228,.45);
  display: grid;
  place-items: center;
  cursor: pointer;
  transition: color 160ms, border-color 160ms;
}
.close-btn:hover { color: var(--paper); border-color: rgba(255,255,255,.3); }
.close-btn svg { width: 15px; height: 15px; fill: currentColor; }
.speaker-tag {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--hot);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .22em;
  margin-bottom: 9px;
}
.speaker-dot { width: 5px; height: 5px; background: var(--hot); border-radius: 50%; box-shadow: 0 0 9px var(--hot); }
.speaker-tag small { margin-left: auto; font-size: 7px; letter-spacing: .18em; color: rgba(248,238,228,.28); font-weight: 500; }
.dialogue-text {
  min-height: 2.8em;
  margin: 0 0 18px;
  font-family: var(--display);
  font-size: clamp(22px, 2.8vw, 31px);
  line-height: 1.3;
  letter-spacing: -.012em;
  color: #fff0e4;
  text-wrap: balance;
}
.dialogue-text::after {
  content: "";
  display: inline-block;
  width: 1px;
  height: .9em;
  margin-left: 4px;
  background: var(--hot);
  vertical-align: -.08em;
  animation: caret 1s steps(2) infinite;
  opacity: 0;
}
.dialogue-text.typing::after { opacity: 1; }
@keyframes caret { 50% { opacity: 0; } }
.dialogue-choices { display: flex; flex-direction: column; gap: 7px; }
.choice-btn {
  display: flex;
  align-items: center;
  gap: 13px;
  width: 100%;
  padding: 12px 16px;
  text-align: left;
  border: 1px solid rgba(255,255,255,.105);
  border-radius: 8px;
  background: rgba(255,255,255,.025);
  color: rgba(251,241,232,.8);
  font-size: 12px;
  line-height: 1.35;
  cursor: pointer;
  transition: border-color 160ms, background 160ms, transform 160ms, color 160ms;
  animation: choice-in 380ms ease both;
  animation-delay: calc(var(--i) * 55ms);
}
@keyframes choice-in { from { opacity: 0; transform: translateY(7px); } to { opacity: 1; transform: translateY(0); } }
.choice-btn:hover { border-color: rgba(255,126,141,.5); background: rgba(255,79,120,.08); color: #fff; transform: translateX(3px); }
.choice-btn:disabled { cursor: default; }
.choice-num {
  flex: 0 0 auto;
  width: 22px;
  height: 22px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(244,198,143,.25);
  border-radius: 50%;
  font-family: var(--mono);
  font-size: 8px;
  color: var(--gold);
}
.choice-btn:hover .choice-num { border-color: var(--hot); color: var(--hot); }
.choice-btn.picked-good { border-color: rgba(127,232,223,.48); background: rgba(127,232,223,.07); }
.choice-btn.picked-neutral { border-color: rgba(244,198,143,.38); }
.choice-btn.picked-bad { border-color: rgba(255,79,120,.25); }
.dialogue-reaction {
  min-height: 0;
  max-height: 0;
  overflow: hidden;
  color: rgba(244,198,143,.78);
  font-family: var(--display);
  font-style: italic;
  font-size: 15px;
  line-height: 1.35;
  transition: max-height 300ms ease, margin 300ms ease;
}
.dialogue-reaction.show { max-height: 70px; margin-top: 10px; }
.continue-row { display: flex; justify-content: flex-end; margin-top: 8px; }
.continue-row .btn-primary { height: 44px; min-width: 0; padding: 0 24px; font-size: 9px; }
.blush-float {
  position: fixed;
  z-index: 50;
  pointer-events: none;
  font-family: var(--display);
  font-style: italic;
  color: var(--hot);
  text-shadow: 0 0 18px rgba(255,79,120,.55);
  animation: floatUp 1.1s ease-out forwards;
}
@keyframes floatUp { from { opacity: 0; transform: translate(-50%, 8px) scale(.9); } 25% { opacity: 1; } to { opacity: 0; transform: translate(-50%, -42px) scale(1.08); } }

/* ---------- pulse ---------- */

.pulse-overlay { display: flex; align-items: center; justify-content: center; }
.pulse-shade {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 48% 54%, rgba(255, 70, 111, .14), transparent 35%),
    linear-gradient(90deg, rgba(4,2,8,.96) 0%, rgba(4,2,8,.74) 44%, rgba(4,2,8,.74) 56%, rgba(4,2,8,.96) 100%);
  backdrop-filter: blur(5px);
  -webkit-backdrop-filter: blur(5px);
}
.pulse-layout {
  position: relative;
  z-index: 2;
  width: min(1000px, calc(100% - 60px));
  display: grid;
  grid-template-columns: minmax(260px, .82fr) minmax(400px, 1.18fr);
  align-items: center;
  gap: clamp(20px, 5vw, 72px);
}
.pulse-head h2 {
  margin: 18px 0 14px;
  font-family: var(--display);
  font-size: clamp(42px, 5vw, 70px);
  line-height: .95;
  letter-spacing: -.035em;
  font-weight: 400;
}
.pulse-head h2 em { color: var(--hot); }
.pulse-head > p {
  max-width: 310px;
  margin: 0;
  color: rgba(248,238,228,.45);
  font-size: 11px;
  line-height: 1.75;
  letter-spacing: .015em;
}
.pulse-stage {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: clamp(10px, 3vw, 36px);
}
.pulse-meter {
  position: relative;
  width: clamp(238px, 29vw, 330px);
  height: clamp(238px, 29vw, 330px);
  flex: 0 0 auto;
}
.pulse-svg { width: 100%; height: 100%; overflow: visible; transform: rotate(-90deg); }
.pulse-track { fill: none; stroke: rgba(255,255,255,.075); stroke-width: 2; }
.pulse-target {
  fill: none;
  stroke: url(#none);
  stroke: var(--hot);
  stroke-width: 7;
  stroke-linecap: round;
  filter: drop-shadow(0 0 7px rgba(255,79,120,.7));
  opacity: .92;
  transition: stroke-dasharray .25s ease;
}
.pulse-track-inner { fill: none; stroke: rgba(255,255,255,.055); stroke-width: 1; stroke-dasharray: 1 8; }
.pulse-glow { fill: rgba(255,79,120,.035); stroke: rgba(255,79,120,.14); stroke-width: 1; }
.pulse-spark {
  position: absolute;
  width: 18px;
  height: 18px;
  left: 50%;
  top: 50%;
  margin: -9px 0 0 -9px;
  border-radius: 50%;
  background: #fff4ee;
  box-shadow: 0 0 8px 2px #fff, 0 0 25px 9px rgba(255,79,120,.75), 0 0 55px 17px rgba(255,79,120,.25);
  will-change: transform;
}
.pulse-spark span {
  position: absolute;
  inset: -7px;
  border: 1px solid rgba(255,148,156,.4);
  border-radius: 50%;
  animation: sparkPing 1.4s ease-out infinite;
}
@keyframes sparkPing { 0% { transform: scale(.55); opacity: .9; } 100% { transform: scale(1.8); opacity: 0; } }
.pulse-center {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}
.pulse-center span { font-family: var(--display); font-style: italic; font-size: 44px; color: rgba(255,246,238,.9); line-height: 1; }
.pulse-center small { font-size: 7px; letter-spacing: .3em; color: rgba(244,198,143,.46); margin-top: 5px; }
.pulse-beat {
  position: absolute;
  inset: 43%;
  border-radius: 50%;
  border: 1px solid rgba(255,79,120,.2);
  opacity: 0;
}
.pulse-beat.beat { animation: beatRing 500ms ease-out; }
@keyframes beatRing { 0% { transform: scale(.7); opacity: .9; } 100% { transform: scale(1.35); opacity: 0; } }
.pulse-side {
  min-width: 145px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 14px;
}
.beat-dots { display: flex; gap: 7px; }
.beat-dots i { width: 17px; height: 3px; background: rgba(255,255,255,.12); border-radius: 3px; transition: background 250ms, box-shadow 250ms; }
