}

function hairFor(style, hairMat, skinMat) {
  const group = new THREE.Group();
  const cap = new THREE.Mesh(new THREE.SphereGeometry(0.287, 16, 12, 0, TAU, 0, Math.PI * 0.7), hairMat);
