    curl.position.set(0.1, 0.2, 0.19);
    curl.rotation.z = -1.2;
    group.add(curl);
  } else {
    const slick = new THREE.Mesh(new THREE.SphereGeometry(0.29, 12, 10), hairMat);
    slick.scale.set(0.92, 0.7, 0.92);
    slick.position.set(0, 0.1, -0.01);
    group.add(slick);
    const pony = new THREE.Mesh(new THREE.CapsuleGeometry(0.09, 0.48, 4, 8), hairMat);
    pony.position.set(0, -0.17, -0.28);
    pony.rotation.x = -0.18;
    group.add(pony);
    const tie = new THREE.Mesh(new THREE.TorusGeometry(0.08, 0.016, 4, 10), material(0xd5a45e, { metalness: 0.6, roughness: 0.3 }));
    tie.position.set(0, 0.08, -0.21);
    tie.rotation.x = Math.PI / 2;
    group.add(tie);
  }
  return group;
}

export function createWoman(style) {
