  moon.shadow.camera.near = 1;
  moon.shadow.camera.far = 55;
  moon.shadow.camera.left = -18;
  moon.shadow.camera.right = 18;
  moon.shadow.camera.top = 18;
  moon.shadow.camera.bottom = -18;
